#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K6: fail if an implementer commit changes a protected path.
A commit with no "Role:" trailer counts as an implementer commit. Human and agent commits follow
the same rule. Usage: protected_paths.py <base>
"""

import subprocess
import sys
from pathlib import Path

sys.dont_write_bytecode = True  # no __pycache__ folder in .cornerstone/lib
sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "lib"))
from path_match import covers  # noqa: E402  the same match as the hook (D62)

PROTECTED = [".claude/", ".cornerstone/", ".cornerstone/checks/", ".github/workflows/", "docs/specs/", "tests/"]
TRAILERS = "commit"  # "commit": the Role trailer. "notes": also the git note (#121).
NOTES_REF = "refs/notes/cornerstone"
ADOPTION = "all"  # "opt-in": a human commit with no Role is not an implementer commit


def git(*args: str) -> str:
    return subprocess.run(["git", *args], check=True, capture_output=True, text=True).stdout


def role_of(sha: str) -> str:
    roles = git("log", "-1", "--format=%(trailers:key=Role,valueonly)", sha).split()
    if not roles and TRAILERS == "notes":
        note = subprocess.run(["git", "notes", f"--ref={NOTES_REF}", "show", sha],
                              capture_output=True, text=True).stdout
        roles = [line.split(":", 1)[1].strip() for line in note.splitlines()
                 if line.lower().startswith("role:")]
    if not roles and ADOPTION == "opt-in":
        actors = git("log", "-1", "--format=%(trailers:key=Actor,valueonly)", sha).split()
        if actors and actors[-1].lower() == "human":
            return "human"
    return roles[-1].lower() if roles else "implementer"



def main(base: str) -> int:
    failures = 0
    if TRAILERS == "notes":  # a note is not in a clone by default
        subprocess.run(["git", "fetch", "-q", "origin", f"{NOTES_REF}:{NOTES_REF}"],
                       capture_output=True)
    for sha in git("rev-list", "--no-merges", f"{base}..HEAD").split():
        role = role_of(sha)
        if role != "implementer":
            continue
        files = git("diff-tree", "--no-commit-id", "--name-only", "-r", sha).split("\n")
        for path in (file for file in files if covers(PROTECTED, file)):
            failures += 1
            print(f"K6: commit {sha[:12]} (Role: {role}) changes {path}, a protected path. "
                  "Revert the change. A test change belongs in a 'Role: tester' commit. A check "
                  "or CI change belongs in a human commit with its own 'Role:' trailer.")
    print(f"K6: {failures} finding(s).")
    return 1 if failures else 0


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: protected_paths.py <base>")
        sys.exit(2)
    sys.exit(main(sys.argv[1]))
